    }

    @Test
    fun `FORGOT_BACKUP_CODE_RECOVERY success passes email_otp as the recovery method`() {
        setUpForgotBackupCodeRecoveryFlow()
        mockStatic(FirebaseAnalyticsUtil::class.java).use { mockAnalytics ->
