            fragment.requireView().findViewById<View>(R.id.personalid_email_resend_button).visibility = View.VISIBLE
        }
        ShadowLooper.idleMainLooper()

        mockWebServer.enqueue(MockResponse().setResponseCode(200).setBody("{}"))
