        }
        ShadowLooper.idleMainLooper()

        mockWebServer.enqueue(MockResponse().setResponseCode(200).setBody("{}"))
        activity.runOnUiThread {
            fragment.requireView().findViewById<View>(R.id.personalid_email_resend_button).performClick()
        }
        ShadowLooper.idleMainLooper()

