     * Verifies an email OTP.
     */
    fun verifyEmailOtp(
        activity: Activity,
        email: String,
        otp: String,
        workflow: EmailWorkFlow,
        sessionData: PersonalIdSessionData?,
        tracker: AttemptTracker = AttemptTracker(),
